  const controls = nodes.filter((n) => !n.ignored && roles.has(n.role?.value));
  const unnamed = controls.filter((n) => !String(n.name?.value ?? "").trim());
  const ids = unnamed.map((n) => n.backendDOMNodeId);
  const html = [];
  for (const backendNodeId of ids) {
    const { outerHTML } = await cdp.send("DOM.getOuterHTML", { backendNodeId });
    html.push(outerHTML.slice(0, 100));
  }
  console.log(`${controls.length} controls; unnamed: ${JSON.stringify(html, null, 1)}`);
  return controls.length > 0 && unnamed.length === 0;
