// Every visible form field has a real label (a <label>, aria-label or aria-labelledby);
// a placeholder alone doesn't count.
async function check(browser, url) {
  const page = await open(browser, url);
  const res = await page.evaluate(() => {
    const fields = [...document.querySelectorAll("input, select, textarea")].filter(
      (el) => !["hidden", "submit", "button", "reset", "image"].includes(el.type) && el.checkVisibility());
    const text = (el) => (el?.textContent ?? "").trim();
    const unlabelled = fields.filter((el) => {
      const aria = (el.getAttribute("aria-label") ?? "").trim();
      const by = (el.getAttribute("aria-labelledby") ?? "").split(/\s+/).filter(Boolean).map((id) => text(document.getElementById(id))).filter(Boolean);
      const labels = [...(el.labels ?? [])].filter((l) => text(l));
      return !aria && by.length === 0 && labels.length === 0;
    });
    return { total: fields.length, unlabelled: unlabelled.map((el) => el.outerHTML.slice(0, 100)) };
  });
  console.log(`${res.total} fields; unlabelled: ${JSON.stringify(res.unlabelled, null, 1)}`);
  return res.total > 0 && res.unlabelled.length === 0;
}
