// The notification on/off settings are real controls: at least three visible checkboxes
// or switches, each of which Space toggles once it has keyboard focus.
async function check(browser, url) {
  const page = await open(browser, url);
  const toggles = page.locator("input[type=checkbox], [role=switch], [role=checkbox]");
  const state = (el) => (el instanceof HTMLInputElement ? String(el.checked) : el.getAttribute("aria-checked"));
  const results = [];
  for (let i = 0; i < (await toggles.count()); i++) {
    const t = toggles.nth(i);
    if (!(await t.evaluate((el) => el.checkVisibility()))) continue;
    await t.focus();
    const focused = await t.evaluate((el) => el === document.activeElement);
    const before = await t.evaluate(state);
    await page.keyboard.press("Space");
    const after = await t.evaluate(state);
    results.push({ focused, toggled: before !== after });
  }
  console.log(`toggles: ${JSON.stringify(results)}`);
  return results.length >= 3 && results.every((r) => r.focused && r.toggled);
}
